    Op(path='backend/app/services/entities/__init__.py', kind='new', final_sha='3fdae99d45fdac37cb97eba1847b91229bb48784c6e7756d8a96bcd136e365c9',
       variants=(),
       content='"""ARCH42-S1:package — Entity Resolution & Document Knowledge Graph.\n\n  vocabulary      every constant the engine and its gates share (pure)\n  normalize       names and identifiers into comparable, validated form (pure)\n  embedding       hashed character/token vectors for ANN blocking (pure)\n  fellegi_sunter  comparison vectors, match weights, EM fitting (pure)\n  annotations     the x-entity vocabulary; extracted fields -> mentions (pure)\n  crypto          identifier HMACs under every configured key; sealing\n  gate            capability.entity_graph: "may resolution run here?"\n  presets         which preset fits a document; enabled presets -> prompt\n  blocking        candidate records: identifier HMAC, pg_trgm, pgvector ANN\n  match_models    the per-workspace, per-kind EM parameters\n  graph           clusters, conflict guard, reversible merge / unmerge / split\n  resolver        one document -> mentions, identifiers, edges, reviews\n  erasure         ARCH-20: documents, subjects and records leave no identifier\n  sweep           the nightly pass (scripts/sweep_entities.py)\n"""\n'),
    Op(path='backend/app/services/entities/annotations.py', kind='new', final_sha='4b28846bba41a9330cb85a076cb5858f480a7b6860995d94b98d7a862ce7c3c0',
       variants=(),
       content='"""ARCH42-S1:annotations — which extracted fields name an entity. Pure.\n\nTHE `x-entity` VOCABULARY\n=========================\n\nA preset schema property may carry `x-entity`:\n\n  {"kind": "PERSON", "role": "candidate"}\n      the field\'s value names an entity (a list names one per element)\n  {"identifier": "EMAIL", "of": "candidate_name"}\n      the value is an identifier of the entity another field names\n  {"kind": "SHIPMENT", "role": "shipment", "identifier": "BL_NUMBER"}\n      the value is BOTH the entity\'s name and its identifier (goods, accounts)\n  "edges": [{"relation": "EMPLOYED_BY", "from": "candidate_name"}]\n      a relationship; "from" X means X -> this, "to" X means this -> X\n  "pairwise": "CONTRACTED_WITH"\n      on a list field: every pair of elements is related\n\nand a schema may carry `x-entity-detect`:\n\n  {"of": "holder_name", "identifiers": ["AADHAAR", "PAN"]}\n      find these identifiers in the document TEXT with their checksums.\n      The Aadhaar/PAN card preset deliberately extracts no number\n      ("Numbers are redacted by default"), so the number never enters\n      work_items.extracted_entities; resolution reads it from the text and\n      stores only its HMAC and the last four digits.\n\nWHERE ANNOTATIONS COME FROM (a correction to the roadmap)\n=========================================================\n\nARCH-38 presets are a catalogue a workspace applies and enables; before\nARCH-42 nothing sent a preset\'s fields to the extraction prompt, so preset\nkeys only appeared by coincidence. ARCH-42 therefore reads annotations from\ntwo places, in one vocabulary:\n\n  1. the preset that fits the document (`presets.select_for_document`), and\n     ARCH-42 wires ENABLED presets into the extraction prompt so their keys\n     actually appear (`presets.prompt_context`);\n  2. BUILTIN_ANNOTATIONS, for the keys the platform\'s generic extraction\n     prompt already produces (vendor_name, candidate_name, party_names...),\n     so invoices, résumés and contracts resolve with no preset at all.\n\nA preset\'s annotation wins over the built-in one for the same field.\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass, field\nfrom typing import Any, Mapping, Optional\n\nfrom app.services.entities import normalize as n\nfrom app.services.entities import vocabulary as v\n\nANNOTATION_KEY = "x-entity"\nDETECT_KEY = "x-entity-detect"\n\n\ndef _subject(kind: str, role: str, **extra: Any) -> dict[str, Any]:\n    return {"kind": kind, "role": role, **extra}\n\n\ndef _identifier(kind: str, of: str) -> dict[str, Any]:\n    return {"identifier": kind, "of": of}\n\n\n#: ARCH42-S1:preset-annotations. What arch42_step1_entity_graph writes into the\n#: 11 platform presets; verify_arch42 asserts the two copies are identical.\nPRESET_ENTITY_ANNOTATIONS: dict[str, dict[str, Any]] = {\n    "resume": {"properties": {\n        "candidate_name": _subject(v.KIND_PERSON, "candidate"),\n        "email": _identifier(v.ID_EMAIL, "candidate_name"),\n        "phone": _identifier(v.ID_PHONE, "candidate_name"),\n        "most_recent_employer": _subject(v.KIND_ORGANIZATION, "employer",\n                                         edges=[{"relation": "EMPLOYED_BY", "from": "candidate_name"}]),\n    }},\n    "offer_letter": {"properties": {\n        "candidate_name": _subject(v.KIND_PERSON, "candidate"),\n    }},\n    "intake_form": {"properties": {\n        "patient_name": _subject(v.KIND_PERSON, "patient"),\n        "date_of_birth": _identifier(v.ID_DATE_OF_BIRTH, "patient_name"),\n        "record_number": _identifier(v.ID_MEDICAL_RECORD, "patient_name"),\n    }},\n    "discharge_summary": {"properties": {\n        "patient_name": _subject(v.KIND_PERSON, "patient"),\n    }},\n    "nda": {"properties": {\n        "disclosing_party": _subject(v.KIND_PARTY, "disclosing_party"),\n        "receiving_party": _subject(v.KIND_PARTY, "receiving_party",\n                                    edges=[{"relation": "CONTRACTED_WITH", "from": "disclosing_party"}]),\n    }},\n    "msa": {"properties": {\n        "customer": _subject(v.KIND_PARTY, "customer"),\n        "supplier": _subject(v.KIND_PARTY, "supplier", edges=[{"relation": "SUPPLIES", "to": "customer"}]),\n    }},\n    "lease": {"properties": {\n        "landlord": _subject(v.KIND_PARTY, "landlord"),\n        "tenant": _subject(v.KIND_PARTY, "tenant", edges=[{"relation": "LEASES_FROM", "to": "landlord"}]),\n        "premises": _subject(v.KIND_ADDRESS, "premises", edges=[\n            {"relation": "OCCUPIES", "from": "tenant"}, {"relation": "LESSOR_OF", "from": "landlord"}]),\n    }},\n    "bill_of_lading": {"properties": {\n        "bl_number": _subject(v.KIND_SHIPMENT, "shipment", identifier=v.ID_BL_NUMBER),\n        "shipper": _subject(v.KIND_PARTY, "shipper", edges=[{"relation": "SHIPPED", "to": "bl_number"}]),\n        "consignee": _subject(v.KIND_PARTY, "consignee", edges=[{"relation": "CONSIGNED_TO", "from": "bl_number"}]),\n        "container_numbers": _subject(v.KIND_ASSET, "container", identifier=v.ID_CONTAINER_NUMBER,\n                                      edges=[{"relation": "CONTAINS", "from": "bl_number"}]),\n    }},\n    "customs_manifest": {"properties": {\n        "declaration_number": _subject(v.KIND_SHIPMENT, "declaration", identifier=v.ID_CUSTOMS_DECLARATION),\n    }},\n    "passport": {"properties": {\n        "holder_name": _subject(v.KIND_PERSON, "holder"),\n        "passport_number": _identifier(v.ID_PASSPORT, "holder_name"),\n    }},\n    "india_id_card": {\n        "properties": {\n            "holder_name": _subject(v.KIND_PERSON, "holder"),\n            "date_of_birth": _identifier(v.ID_DATE_OF_BIRTH, "holder_name"),\n        },\n        "detect": {"of": "holder_name", "identifiers": [v.ID_AADHAAR, v.ID_PAN]},\n    },\n}\n\n_CUSTOMER = _subject(v.KIND_PARTY, "customer", edges=[{"relation": "SUPPLIES", "from": "vendor_name"}])\n_ACCOUNT_EDGES = [{"relation": "HOLDS_ACCOUNT", "from": "vendor_name"}]\n\n#: The keys ENTITY_EXTRACTION_PROMPT_TEMPLATE (app/services/llm_service.py)\n#: asks for, plus the spellings models commonly return for them.\nBUILTIN_ANNOTATIONS: dict[str, dict[str, Any]] = {\n    "vendor_name": _subject(v.KIND_ORGANIZATION, "vendor"),\n    "supplier_name": _subject(v.KIND_ORGANIZATION, "vendor"),\n    "vendor_gstin": _identifier(v.ID_GSTIN, "vendor_name"),\n    "gstin": _identifier(v.ID_GSTIN, "vendor_name"),\n    "gst_number": _identifier(v.ID_GSTIN, "vendor_name"),\n    "vendor_pan": _identifier(v.ID_PAN, "vendor_name"),\n    "vendor_email": _identifier(v.ID_EMAIL, "vendor_name"),\n    "vendor_phone": _identifier(v.ID_PHONE, "vendor_name"),\n    "vendor_address": _subject(v.KIND_ADDRESS, "vendor_address", edges=[{"relation": "LOCATED_AT", "from": "vendor_name"}]),\n    "customer_name": _CUSTOMER,\n    "bill_to": _CUSTOMER,\n    "buyer_name": _CUSTOMER,\n    "iban": _subject(v.KIND_ACCOUNT, "bank_account", identifier=v.ID_IBAN, edges=_ACCOUNT_EDGES),\n    "bank_account_number": _subject(v.KIND_ACCOUNT, "bank_account", identifier=v.ID_ACCOUNT_NUMBER, edges=_ACCOUNT_EDGES),\n    "candidate_name": _subject(v.KIND_PERSON, "candidate"),\n    "email": _identifier(v.ID_EMAIL, "candidate_name"),\n    "phone_number": _identifier(v.ID_PHONE, "candidate_name"),\n    "party_names": _subject(v.KIND_PARTY, "party", pairwise="CONTRACTED_WITH"),\n}\n\n\nclass AnnotationError(ValueError):\n    def __init__(self, code: str, message: str) -> None:\n        super().__init__(message)\n        self.code = code\n        self.message = message\n\n\ndef validate_annotation(field_name: str, annotation: Any, properties: Mapping[str, Any]) -> None:\n    """Refuse an `x-entity` block the resolver could not act on."""\n    if not isinstance(annotation, dict):\n        raise AnnotationError("ENTITY_ANNOTATION_SHAPE", f"{field_name}: x-entity must be an object.")\n    unknown = set(annotation) - {"kind", "role", "identifier", "of", "edges", "pairwise"}\n    if unknown:\n        raise AnnotationError("ENTITY_ANNOTATION_KEYS", f"{field_name}: unknown x-entity keys {sorted(unknown)}.")\n    kind, identifier = annotation.get("kind"), annotation.get("identifier")\n    if kind is None and identifier is None:\n        raise AnnotationError("ENTITY_ANNOTATION_EMPTY", f"{field_name}: x-entity needs a kind or an identifier.")\n    if kind is not None and kind not in v.ANNOTATION_KINDS:\n        raise AnnotationError("ENTITY_ANNOTATION_KIND", f"{field_name}: {kind!r} is not an entity kind.")\n    if identifier is not None and identifier not in v.IDENTIFIER_KINDS:\n        raise AnnotationError("ENTITY_ANNOTATION_IDENTIFIER", f"{field_name}: {identifier!r} is not an identifier kind.")\n    if kind is None and annotation.get("of") not in properties:\n        raise AnnotationError("ENTITY_ANNOTATION_OF", f"{field_name}: an identifier needs \'of\' naming another field.")\n    if kind is not None and identifier is not None and identifier not in v.IDENTIFIERS_BY_ENTITY_KIND.get(kind, ()):\n        raise AnnotationError("ENTITY_ANNOTATION_IDENTIFIER", f"{field_name}: a {kind} cannot be named by {identifier}.")\n    if kind is not None and not isinstance(annotation.get("role"), str):\n        raise AnnotationError("ENTITY_ANNOTATION_ROLE", f"{field_name}: an entity field needs a role.")\n    for edge in annotation.get("edges", []) or []:\n        if not isinstance(edge, dict) or edge.get("relation") not in v.RELATIONS:\n            raise AnnotationError("ENTITY_ANNOTATION_EDGE", f"{field_name}: edge relation must be one of {list(v.RELATIONS)}.")\n        other = edge.get("from", edge.get("to"))\n        if ("from" in edge) == ("to" in edge) or other not in properties:\n            raise AnnotationError("ENTITY_ANNOTATION_EDGE", f"{field_name}: an edge names exactly one of from/to, a field of this schema.")\n    if annotation.get("pairwise") is not None and annotation["pairwise"] not in v.RELATIONS:\n        raise AnnotationError("ENTITY_ANNOTATION_EDGE", f"{field_name}: pairwise must be a relation.")\n\n\ndef validate_schema_annotations(schema: Mapping[str, Any]) -> None:\n    properties = schema.get("properties") or {}\n    for name, definition in properties.items():\n        if isinstance(definition, dict) and ANNOTATION_KEY in definition:\n            validate_annotation(name, definition[ANNOTATION_KEY], properties)\n    detect = schema.get(DETECT_KEY)\n    if detect is not None:\n        if (not isinstance(detect, dict) or detect.get("of") not in properties\n                or not set(detect.get("identifiers") or []) <= set(v.IDENTIFIER_KINDS)):\n            raise AnnotationError("ENTITY_ANNOTATION_DETECT", "x-entity-detect needs \'of\' (a field) and known identifiers.")\n\n\ndef annotations_from_schema(schema: Mapping[str, Any]) -> tuple[dict[str, dict], Optional[dict]]:\n    properties = schema.get("properties") or {}\n    found = {k: d[ANNOTATION_KEY] for k, d in properties.items() if isinstance(d, dict) and ANNOTATION_KEY in d}\n    return found, schema.get(DETECT_KEY)\n\n\n# ---------------------------------------------------------------------------\n# Extraction: fields -> mention specs\n# ---------------------------------------------------------------------------\n\n\n@dataclass\nclass MentionSpec:\n    key: str\n    field_path: str\n    ordinal: int\n    kind: str\n    role: str\n    surface: str\n    normalized: str\n    source: str\n    identifiers: list[tuple[str, str, bool]] = field(default_factory=list)  # (kind, value, derived)\n\n\n@dataclass(frozen=True)\nclass EdgeSpec:\n    relation: str\n    src_key: str\n    dst_key: str\n\n\n_KEY = re.compile(r"[^0-9a-z]+")\n\n\ndef field_key(name: str) -> str:\n    return _KEY.sub("_", str(name).strip().lower()).strip("_")\n\n\ndef _values(raw: Any) -> list[str]:\n    if raw is None:\n        return []\n    if isinstance(raw, list):\n        return [str(x).strip() for x in raw if isinstance(x, (str, int, float)) and str(x).strip()]\n    if isinstance(raw, (str, int, float)) and not isinstance(raw, bool) and str(raw).strip():\n        return [str(raw).strip()]\n    return []\n\n\ndef _add_identifier(spec: MentionSpec, kind: str, value: str) -> None:\n    if kind not in v.IDENTIFIERS_BY_ENTITY_KIND.get(spec.kind, ()):\n        return\n    if (kind, value, False) not in spec.identifiers:\n        spec.identifiers.append((kind, value, False))\n    if kind == v.ID_GSTIN:\n        pan = n.gstin_pan(value)\n        if pan and (v.ID_PAN, pan, True) not in spec.identifiers and (v.ID_PAN, pan, False) not in spec.identifiers:\n            spec.identifiers.append((v.ID_PAN, pan, True))\n\n\ndef extract(\n    extracted: Mapping[str, Any],\n    annotations: Mapping[str, Mapping[str, Any]],\n    *,\n    sources: Mapping[str, str],\n    detect: Optional[Mapping[str, Any]] = None,\n    text: str = "",\n) -> tuple[list[MentionSpec], list[EdgeSpec]]:\n    """Mentions and edges one document\'s extracted fields support."""\n    values = {field_key(k): raw for k, raw in (extracted or {}).items()}\n    by_field: dict[str, list[MentionSpec]] = {}\n\n    for name, ann in annotations.items():\n        kind = ann.get("kind")\n        if kind is None:\n            continue\n        for ordinal, raw in enumerate(_values(values.get(name))):\n            identifier = ann.get("identifier")\n            if identifier:\n                value = n.normalize_identifier(identifier, raw)\n                if value is None:\n                    continue\n                surface = n.mask(identifier, value)\n                resolved = kind\n                normalized = surface.casefold()\n            else:\n                resolved = n.party_kind(raw) if kind == v.KIND_PARTY else kind\n                surface = n.clean_display(raw)\n                normalized = n.normalize_name(resolved, raw)\n                if not normalized or not any(c.isalpha() for c in normalized):\n                    continue\n            spec = MentionSpec(\n                key=f"{name}#{ordinal}", field_path=name, ordinal=ordinal, kind=resolved,\n                role=str(ann.get("role") or name)[:48], surface=surface, normalized=normalized,\n                source=sources.get(name, v.SOURCE_BUILTIN),\n            )\n            if identifier:\n                _add_identifier(spec, identifier, value)\n            by_field.setdefault(name, []).append(spec)\n\n    for name, ann in annotations.items():\n        identifier, of = ann.get("identifier"), ann.get("of")\n        if ann.get("kind") is not None or not identifier or of not in by_field or len(by_field[of]) != 1:\n            continue\n        subject = by_field[of][0]\n        for raw in _values(values.get(name)):\n            value = n.normalize_identifier(identifier, raw)\n            if value is not None:\n                _add_identifier(subject, identifier, value)\n\n    if detect and detect.get("of") in by_field and len(by_field[detect["of"]]) == 1:\n        subject = by_field[detect["of"]][0]\n        for kind, value in n.detect_identifiers(text, tuple(detect.get("identifiers") or ())):\n            before = len(subject.identifiers)\n            _add_identifier(subject, kind, value)\n            if len(subject.identifiers) > before:\n                subject.source = subject.source if subject.source != v.SOURCE_BUILTIN else v.SOURCE_DETECTOR\n\n    edges: list[EdgeSpec] = []\n    for name, ann in annotations.items():\n        mine = by_field.get(name, [])\n        for edge in ann.get("edges", []) or []:\n            other = by_field.get(edge.get("from", edge.get("to")), [])\n            for a in mine:\n                for b in other:\n                    src, dst = (b, a) if "from" in edge else (a, b)\n                    if src.key != dst.key:\n                        edges.append(EdgeSpec(edge["relation"], src.key, dst.key))\n        if ann.get("pairwise"):\n            for i, a in enumerate(mine):\n                for b in mine[i + 1:]:\n                    edges.append(EdgeSpec(ann["pairwise"], a.key, b.key))\n\n    specs = [s for group in by_field.values() for s in group]\n    return specs, list(dict.fromkeys(edges))\n\n\ndef merged_annotations(\n    preset: Optional[tuple[Mapping[str, Any], Optional[Mapping[str, Any]]]],\n) -> tuple[dict[str, dict], dict[str, str], Optional[dict]]:\n    """Built-in annotations overlaid by the chosen preset\'s."""\n    combined: dict[str, dict] = {k: dict(a) for k, a in BUILTIN_ANNOTATIONS.items()}\n    sources = {k: v.SOURCE_BUILTIN for k in combined}\n    detect = None\n    if preset is not None:\n        fields, detect = preset\n        for key, ann in fields.items():\n            combined[key] = dict(ann)\n            sources[key] = v.SOURCE_PRESET\n    return combined, sources, (dict(detect) if detect else None)\n'),
    Op(path='backend/app/services/entities/blocking.py', kind='new', final_sha='85140a2882638698b9bf6bc579949d6636ed72f2fb85c6bdb3a75fffffacdcea',
       variants=(),
       content='"""ARCH42-S1:blocking — which existing records a mention could be.\n\nComparing a mention with every record in a workspace is quadratic and wrong\ntwice over: slow, and a model scoring a million implausible pairs finds some\nthat look plausible. Three passes produce the candidates, and only they are\nscored:\n\n  1. HARD IDENTIFIER: the mention\'s hard identifiers as HMACs under every\n     configured key generation; an exact hit is a link, not a candidate.\n  2. pg_trgm: `normalized_name % :q` over the GIN trigram index — typo and\n     spelling variants ("Accme Suplies").\n  3. pgvector ANN: cosine distance over the HNSW index of hashed name vectors\n     — reordered and partial names ("Kumar Ravi", "R Kumar"). The workspace\n     and kind filter runs with `hnsw.iterative_scan = relaxed_order`\n     (pgvector >= 0.8), so a filter that discards most of the nearest\n     neighbours scans further instead of returning nothing.\n"""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Iterable, Optional, Sequence\n\nfrom sqlalchemy import select, text, tuple_\nfrom sqlalchemy.orm import Session\n\nfrom app.models.entity_graph import Entity, EntityIdentifier\nfrom app.services.entities import crypto\nfrom app.services.entities import vocabulary as v\n\nANN_MIN_COSINE = 0.45\n\n\ndef identifier_matches(\n    db: Session, *, workspace_id: uuid.UUID, entity_kind: str, identifiers: Iterable[tuple[str, str]]\n) -> dict[uuid.UUID, set[str]]:\n    """entity id -> the hard identifier kinds it shares with the mention."""\n    pairs: list[tuple[str, str]] = []\n    for kind, value in identifiers:\n        if kind in v.HARD_IDENTIFIER_KINDS:\n            pairs += [(kind, digest) for digest in crypto.lookup_digests(kind, value)]\n    if not pairs:\n        return {}\n    rows = db.execute(\n        select(EntityIdentifier.entity_id, EntityIdentifier.kind).where(\n            EntityIdentifier.workspace_id == workspace_id,\n            EntityIdentifier.entity_kind == entity_kind,\n            tuple_(EntityIdentifier.kind, EntityIdentifier.value_hmac).in_(pairs),\n        )\n    ).all()\n    found: dict[uuid.UUID, set[str]] = {}\n    for entity_id, kind in rows:\n        found.setdefault(entity_id, set()).add(kind)\n    return found\n\n\ndef existing_identifier_ids(\n    db: Session, *, entity_ids: Sequence[uuid.UUID], kind: str, value: str\n) -> list[uuid.UUID]:\n    digests = crypto.lookup_digests(kind, value)\n    if not entity_ids:\n        return []\n    return list(db.execute(select(EntityIdentifier.id).where(\n        EntityIdentifier.entity_id.in_(list(entity_ids)),\n        EntityIdentifier.kind == kind,\n        EntityIdentifier.value_hmac.in_(digests),\n    )).scalars())\n\n\ndef trigram_candidates(db: Session, *, workspace_id: uuid.UUID, kind: str, normalized: str) -> list[uuid.UUID]:\n    if not normalized:\n        return []\n    db.execute(text("SELECT set_config(\'pg_trgm.similarity_threshold\', :t, true)"), {"t": str(v.TRIGRAM_THRESHOLD)})\n    return list(db.execute(\n        text(\n            "SELECT id FROM entities WHERE workspace_id = :ws AND kind = :kind AND normalized_name % :q "\n            "ORDER BY similarity(normalized_name, :q) DESC LIMIT :limit"\n        ),\n        {"ws": workspace_id, "kind": kind, "q": normalized, "limit": v.TRIGRAM_LIMIT},\n    ).scalars())\n\n\ndef ann_candidates(db: Session, *, workspace_id: uuid.UUID, kind: str, vector: Optional[Sequence[float]]) -> list[uuid.UUID]:\n    if vector is None or len(vector) == 0:\n        return []\n    vector = [float(x) for x in vector]\n    db.execute(text("SELECT set_config(\'hnsw.iterative_scan\', \'relaxed_order\', true)"))\n    distance = Entity.name_embedding.cosine_distance(vector)\n    rows = db.execute(\n        select(Entity.id, distance.label("d")).where(\n            Entity.workspace_id == workspace_id, Entity.kind == kind, Entity.name_embedding.is_not(None)\n        ).order_by(distance).limit(v.ANN_LIMIT)\n    ).all()\n    return [row.id for row in rows if 1.0 - float(row.d) >= ANN_MIN_COSINE]\n\n\ndef name_candidates(\n    db: Session, *, workspace_id: uuid.UUID, kind: str, normalized: str, vector: Optional[Sequence[float]]\n) -> list[uuid.UUID]:\n    seen: dict[uuid.UUID, None] = {}\n    for entity_id in trigram_candidates(db, workspace_id=workspace_id, kind=kind, normalized=normalized):\n        seen.setdefault(entity_id)\n    for entity_id in ann_candidates(db, workspace_id=workspace_id, kind=kind, vector=vector):\n        seen.setdefault(entity_id)\n    return list(seen)\n'),
    Op(path='backend/app/services/entities/crypto.py', kind='new', final_sha='b7ab452a0b82c8d5ab9dfe41e35890d5d916edc49617b971cbb4fdd98265e4e8',
       variants=(),
       content='"""ARCH42-S1:crypto — identifier HMACs that survive key rotation.\n\nWHY NOT app/services/redaction/token_digest\n===========================================\n\nARCH-32\'s digest says, in its own docstring, that it is NOT a lookup key and\nstops comparing equal after a key rotation. An entity identifier IS a lookup\nkey: "does this workspace already hold this PAN?" is the whole point. So:\n\n  * the MAC key is derived per configured encryption key (HKDF, a domain\n    separated info string), not from the head key alone;\n  * a LOOKUP computes the digest under every configured key, so a value\n    stored before a rotation is still found while the old key is configured;\n  * every row records its key GENERATION, and the nightly sweep re-keys rows\n    to the head generation by decrypting their stored value;\n  * Aadhaar rows keep no value (HMAC + last four only), so they cannot be\n    re-keyed: once the old key is removed they stop matching, which fails\n    safe (a new record and a review), never towards a wrong link.\n\nNo plaintext identifier is ever stored. `display_ciphertext` is the MASKED\nform, encrypted; `value_ciphertext` is the full value, encrypted, kept only so\nrotation can re-key (and never for Aadhaar).\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport hmac\nfrom functools import lru_cache\nfrom typing import Optional\n\nfrom app.services.entities.vocabulary import HMAC_INFO\n\n\nclass IdentifierKeyError(RuntimeError):\n    """No key material. Never carries the value."""\n\n\ndef _configured_keys() -> tuple[str, ...]:\n    from app.core.config import settings\n\n    keys = tuple(str(k) for k in (getattr(settings, "encryption_key_list", None) or []))\n    if not keys:\n        raise IdentifierKeyError(\n            "No encryption keys are configured (EMAIL_ENCRYPTION_KEYS). An "\n            "unkeyed identifier digest would be a brute-forceable hash of every "\n            "PAN and Aadhaar number in the workspace."\n        )\n    return keys\n\n\n@lru_cache(maxsize=16)\ndef _derive(material: str) -> tuple[str, bytes]:\n    from app.services.redaction.token_digest import _hkdf_sha256\n\n    raw = material.encode("utf-8")\n    generation = hashlib.sha256(b"flowpilot/arch42/key-generation\\x00" + raw).hexdigest()[:16]\n    return generation, _hkdf_sha256(raw, info=HMAC_INFO)\n\n\ndef _mac(key: bytes, kind: str, value: str) -> str:\n    return hmac.new(key, f"{kind}\\x1f{value}".encode("utf-8"), hashlib.sha256).hexdigest()\n\n\ndef head_generation() -> str:\n    return _derive(_configured_keys()[0])[0]\n\n\ndef head_digest(kind: str, value: str) -> tuple[str, str]:\n    """(generation, hex digest) under the newest key. What a new row stores."""\n    generation, key = _derive(_configured_keys()[0])\n    return generation, _mac(key, kind, value)\n\n\ndef lookup_digests(kind: str, value: str) -> list[str]:\n    """The value\'s digest under EVERY configured key, newest first."""\n    return [_mac(_derive(material)[1], kind, value) for material in _configured_keys()]\n\n\ndef digest_under(generation: str, kind: str, value: str) -> Optional[str]:\n    for material in _configured_keys():\n        gen, key = _derive(material)\n        if gen == generation:\n            return _mac(key, kind, value)\n    return None\n\n\ndef seal(text: str) -> str:\n    from app.core.encryption import encrypt_secret\n\n    return encrypt_secret(text)\n\n\ndef open_sealed(ciphertext: Optional[str]) -> Optional[str]:\n    if not ciphertext:\n        return None\n    from app.core.encryption import decrypt_secret\n\n    try:\n        return decrypt_secret(ciphertext)\n    except Exception:  # noqa: BLE001 - a rotated-away key loses one display, not the page\n        return None\n'),
    Op(path='backend/app/services/entities/embedding.py', kind='new', final_sha='4c0ea45899f0877a658eb375dd0f662c2b4f9901bb68f25cd0b3237e3ffe21f9',
       variants=(),
       content='"""ARCH42-S1:embedding — a name\'s vector for the ANN blocking pass. Pure.\n\nWHY NOT THE SENTENCE-TRANSFORMER\n================================\n\nTwo reasons, one practical and one about what a name is.\n\nPractical: resolution runs as `entities.resolve_document` on the LIGHT worker\nprofile, and `assert_imports_match_profile()` refuses to boot a LIGHT worker\nthat imports sentence_transformers or torch (app/workers/profiles.py). ARCH-31\nrecorded the same constraint for procurement similarity.\n\nWhat a name is: "Acme Supplies" and "Globex Supplies" are, to a semantic\nmodel, near neighbours (two supply companies). To entity resolution they are\ndifferent parties, and "Accme Suplies" is the neighbour that matters. Signed\nfeature hashing over character trigrams and whole tokens is deterministic\nacross processes, needs no model, puts typo variants and reordered tokens\n("Kumar Ravi") close, and keeps unrelated names apart. pgvector\'s HNSW index\nover these vectors is the approximate-nearest-neighbour pass the roadmap asks\nfor; `hnsw.iterative_scan` (pgvector >= 0.8) keeps the workspace filter from\nstarving the result.\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport math\nfrom typing import Optional, Sequence\n\nfrom app.services.entities.vocabulary import EMBEDDING_DIM\n\n\ndef _bucket(feature: str) -> tuple[int, float]:\n    digest = hashlib.sha1(feature.encode("utf-8")).digest()\n    return int.from_bytes(digest[:4], "big") % EMBEDDING_DIM, (1.0 if digest[4] & 1 else -1.0)\n\n\ndef name_vector(normalized_name: str) -> Optional[list[float]]:\n    """L2-normalised hashed trigram + token vector, or None for an empty name."""\n    text = (normalized_name or "").strip()\n    if not text:\n        return None\n    vector = [0.0] * EMBEDDING_DIM\n    features: list[tuple[str, float]] = []\n    for token in text.split():\n        padded = f" {token} "\n        features.append((f"t:{token}", 2.0))\n        features += [(f"g:{padded[i:i + 3]}", 1.0) for i in range(len(padded) - 2)]\n    for feature, weight in features:\n        index, sign = _bucket(feature)\n        vector[index] += sign * weight\n    norm = math.sqrt(sum(x * x for x in vector))\n    return [x / norm for x in vector] if norm else None\n\n\ndef cosine(a: Sequence[float], b: Sequence[float]) -> float:\n    dot = sum(x * y for x, y in zip(a, b))\n    na = math.sqrt(sum(x * x for x in a))\n    nb = math.sqrt(sum(y * y for y in b))\n    return dot / (na * nb) if na and nb else 0.0\n'),
    Op(path='backend/app/services/entities/erasure.py', kind='new', final_sha='15653051d68d448cfc45c0781e547ad029cb8222212b59ad28b20110f97533d5',
       variants=(),
       content='"""ARCH42-S1:erasure — ARCH-20 erasure leaves no identifier behind.\n\nThree entry points, one rule: when content is erased, every identifier row\nthat content evidenced goes with it, and a record left with nothing is removed.\n\n  erase_for_work_items   ARCH-20 `_destroy_documents`: the subject\'s documents\n                         lose their mentions and the edges they evidenced;\n                         identifiers and records only they supported go too.\n  erase_by_identifier    ARCH-20 `erase_subject`: the record(s) holding the\n                         subject\'s own email (matched by HMAC under every key\n                         generation — the value itself is never stored) are\n                         removed whole: the subject IS that record.\n  erase_cluster          the console\'s "erase this record" (ADMIN): a patient\n                         or a person asks to be forgotten.\n"""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Iterable, Optional\n\nfrom sqlalchemy import delete, select\nfrom sqlalchemy.orm import Session\n\nfrom app.models.entity_graph import Entity, EntityEdge, EntityIdentifier, EntityMention\nfrom app.services.entities import crypto, graph\nfrom app.services.entities import normalize as n\n\n\ndef erase_for_work_items(db: Session, work_item_ids: Iterable[uuid.UUID]) -> dict[str, int]:\n    ids = list(work_item_ids)\n    if not ids:\n        return {"mentions": 0, "edges": 0, "identifiers": 0, "entities": 0}\n    workspaces = set(db.execute(select(EntityMention.workspace_id).where(\n        EntityMention.work_item_id.in_(ids)).distinct()).scalars())\n    counts = {\n        "mentions": db.execute(delete(EntityMention).where(EntityMention.work_item_id.in_(ids))).rowcount or 0,\n        "edges": db.execute(delete(EntityEdge).where(EntityEdge.evidence_work_item_id.in_(ids))).rowcount or 0,\n        "identifiers": 0,\n        "entities": 0,\n    }\n    for workspace_id in workspaces:\n        orphans = graph.collect_orphans(db, workspace_id=workspace_id)\n        counts["identifiers"] += orphans["identifiers"]\n        counts["entities"] += orphans["entities"]\n    db.flush()\n    return counts\n\n\ndef erase_cluster(db: Session, *, entity_id: uuid.UUID) -> dict[str, int]:\n    root = graph.root_of(db, entity_id)\n    return graph.delete_cluster(db, root.id)\n\n\ndef erase_by_identifier(\n    db: Session, *, workspace_ids: Iterable[uuid.UUID], kind: str, raw_value: str\n) -> dict[str, int]:\n    value = n.normalize_identifier(kind, raw_value)\n    totals = {"entities": 0, "identifiers": 0, "mentions": 0, "edges": 0, "candidates": 0}\n    if value is None:\n        return totals\n    holders = set(db.execute(select(EntityIdentifier.entity_id).where(\n        EntityIdentifier.workspace_id.in_(list(workspace_ids)), EntityIdentifier.kind == kind,\n        EntityIdentifier.value_hmac.in_(crypto.lookup_digests(kind, value)))).scalars())\n    roots: set[uuid.UUID] = set()\n    for entity_id in holders:\n        if db.get(Entity, entity_id) is not None:\n            roots.add(graph.root_of(db, entity_id).id)\n    for root_id in roots:\n        for key, count in graph.delete_cluster(db, root_id).items():\n            totals[key] = totals.get(key, 0) + count\n    return totals\n'),
    Op(path='backend/app/services/entities/fellegi_sunter.py', kind='new', final_sha='63beefc3ad6b171565523ddfa1bde97976833f4e1098d2f90a19daf61083f2e8',
       variants=(),
       content='"""ARCH42-S1:fellegi-sunter — match weights, fitted by EM. Pure.\n\nTHE MODEL\n=========\n\nFor two records a and b, each COMPARISON c (name, email, phone, date of\nbirth, exclusive identifier) takes a LEVEL: the name has four (different,\nsimilar, very similar, exact), the others two (disagree, agree), and any of\nthem may be MISSING when either side lacks the field. Fellegi and Sunter\n(1969): with m_c(l) = P(level l | same entity) and u_c(l) = P(level l |\ndifferent entities), and assuming the comparisons are conditionally\nindependent given the true status, the posterior that a and b are the same is\n\n    p = lam * prod m_c(l_c) / (lam * prod m_c(l_c) + (1 - lam) * prod u_c(l_c))\n\nwhere lam is the prior match rate among the candidate pairs blocking produced.\nA missing comparison contributes a factor of 1 to both products: absence of a\nphone number is not evidence either way. The match WEIGHT is log2 of the\nlikelihood ratio, the number the console shows next to a merge proposal.\n\nEM\n==\n\nNo one labels pairs. The mixture is fitted by Expectation-Maximisation\n(Dempster, Laird & Rubin 1977; Winkler 1988 for record linkage): the E-step\ncomputes each pair\'s posterior g under the current parameters, the M-step sets\nm to the g-weighted level frequencies, u to the (1 - g)-weighted ones and lam\nto the mean g. Pairs are compressed to distinct comparison PATTERNS with\ncounts, so a sweep over 20,000 pairs costs a few hundred pattern updates per\niteration. The log-likelihood never decreases (the gates assert it), and the\nfit stops when no parameter moves by more than EM_TOLERANCE.\n\nTwo guards keep a fit honest. Parameters are floored at PROBABILITY_FLOOR so\none unseen level cannot zero a product. And the LABEL guard: EM is symmetric\nin "match" and "non-match", so if the fitted "match" class makes an exact name\nLESS likely than the non-match class, the labels are swapped back.\n\nTHE CONFLICT GUARD IS NOT PART OF THE MODEL\n===========================================\n\n`conflicts()` is a rule, not a weight. Two clusters holding different values of\nan EXCLUSIVE identifier (two PANs, two Aadhaar numbers) never merge without a\nhuman, however high the model scores the names. The model is still told about\nthe disagreement (the `exclusive` comparison), so it scores such a pair low as\nwell — but a mis-fitted model must not be able to override the rule.\n"""\n\nfrom __future__ import annotations\n\nimport math\nfrom collections import Counter\nfrom dataclasses import dataclass, field\nfrom typing import Iterable, Mapping, Optional, Sequence\n\nfrom app.services.entities import normalize as n\nfrom app.services.entities import vocabulary as v\n\nLEVELS: dict[str, int] = {"name": 4, "email": 2, "phone": 2, "dob": 2, "exclusive": 2}\n\nCOMPARISONS: dict[str, tuple[str, ...]] = {\n    v.KIND_PERSON: ("name", "email", "phone", "dob", "exclusive"),\n    v.KIND_ORGANIZATION: ("name", "email", "phone", "exclusive"),\n    v.KIND_ADDRESS: ("name",),\n}\n\n_ID_FOR = {"email": v.ID_EMAIL, "phone": v.ID_PHONE, "dob": v.ID_DATE_OF_BIRTH}\n\n\n@dataclass(frozen=True)\nclass Profile:\n    """What resolution compares: a record\'s names and its identifier digests.\n\n    `identifiers` maps identifier kind -> digests under the HEAD key\n    generation only; digests under other generations are not comparable and\n    are left out (treated as missing, never as disagreement).\n    """\n\n    kind: str\n    names: tuple[str, ...]\n    identifiers: Mapping[str, frozenset[str]] = field(default_factory=dict)\n\n\ndef name_level(a_names: Sequence[str], b_names: Sequence[str]) -> Optional[int]:\n    best: Optional[int] = None\n    for a in a_names:\n        for b in b_names:\n            if not a or not b:\n                continue\n            if a == b:\n                return 3\n            jw = n.jaro_winkler(a, b)\n            level = 2 if (jw >= 0.92 or n.token_set_equal(a, b)) else 1 if (jw >= 0.80 or n.initials_compatible(a, b)) else 0\n            best = level if best is None else max(best, level)\n    return best\n\n\ndef _set_level(a: frozenset, b: frozenset) -> Optional[int]:\n    if not a or not b:\n        return None\n    return 1 if a & b else 0\n\n\ndef conflicts(a: Mapping[str, frozenset], b: Mapping[str, frozenset]) -> list[str]:\n    """Exclusive identifier kinds both sides hold with no value in common."""\n    return sorted(\n        kind for kind in v.EXCLUSIVE_IDENTIFIER_KINDS\n        if a.get(kind) and b.get(kind) and not (a[kind] & b[kind])\n    )\n\n\ndef compare(a: Profile, b: Profile) -> dict[str, Optional[int]]:\n    gamma: dict[str, Optional[int]] = {}\n    for comparison in COMPARISONS.get(a.kind, ("name",)):\n        if comparison == "name":\n            gamma["name"] = name_level(a.names, b.names)\n        elif comparison == "exclusive":\n            shared = [k for k in v.EXCLUSIVE_IDENTIFIER_KINDS if a.identifiers.get(k) and b.identifiers.get(k)]\n            if not shared:\n                gamma["exclusive"] = None\n            else:\n                gamma["exclusive"] = 0 if conflicts(a.identifiers, b.identifiers) else 1\n        else:\n            kind = _ID_FOR[comparison]\n            gamma[comparison] = _set_level(a.identifiers.get(kind, frozenset()), b.identifiers.get(kind, frozenset()))\n    return gamma\n\n\n# ---------------------------------------------------------------------------\n# Parameters\n# ---------------------------------------------------------------------------\n\n\n@dataclass\nclass Model:\n    kind: str\n    lam: float\n    m: dict[str, list[float]]\n    u: dict[str, list[float]]\n\n    def as_json(self) -> dict:\n        return {"lambda": self.lam, "m": self.m, "u": self.u}\n\n    @classmethod\n    def from_json(cls, kind: str, data: Mapping) -> "Model":\n        return cls(kind, float(data["lambda"]), {k: list(map(float, x)) for k, x in data["m"].items()},\n                   {k: list(map(float, x)) for k, x in data["u"].items()})\n\n\n#: Platform priors: what a workspace uses until it has MIN_PAIRS_TO_FIT pairs.\n#: A PERSON name alone is weak evidence (many people share one); an\n#: ORGANIZATION name that matches exactly after legal suffixes are removed is\n#: strong. Levels are low-to-high: name (different, similar, very similar,\n#: exact), others (disagree, agree).\n_PRIOR_NAME = {\n    v.KIND_PERSON: ([0.03, 0.10, 0.25, 0.62], [0.90, 0.08, 0.015, 0.005]),\n    v.KIND_ORGANIZATION: ([0.02, 0.06, 0.12, 0.80], [0.95, 0.04, 0.008, 0.002]),\n    v.KIND_ADDRESS: ([0.03, 0.07, 0.20, 0.70], [0.95, 0.045, 0.004, 0.001]),\n}\n_PRIOR_OTHER = {\n    "email": ([0.15, 0.85], [0.9995, 0.0005]),\n    "phone": ([0.20, 0.80], [0.995, 0.005]),\n    "dob": ([0.05, 0.95], [0.997, 0.003]),\n    "exclusive": ([0.02, 0.98], [0.99999, 0.00001]),\n}\n\n\ndef prior(kind: str) -> Model:\n    comparisons = COMPARISONS.get(kind, ("name",))\n    m, u = {}, {}\n    for c in comparisons:\n        mm, uu = _PRIOR_NAME[kind] if c == "name" else _PRIOR_OTHER[c]\n        m[c], u[c] = list(mm), list(uu)\n    return Model(kind, 0.10, m, u)\n\n\ndef likelihoods(model: Model, gamma: Mapping[str, Optional[int]]) -> tuple[float, float]:\n    pm, pu = 1.0, 1.0\n    for c, level in gamma.items():\n        if level is None or c not in model.m:\n            continue\n        pm *= model.m[c][level]\n        pu *= model.u[c][level]\n    return pm, pu\n\n\ndef posterior(model: Model, gamma: Mapping[str, Optional[int]]) -> float:\n    pm, pu = likelihoods(model, gamma)\n    top = model.lam * pm\n    bottom = top + (1.0 - model.lam) * pu\n    return top / bottom if bottom > 0 else 0.0\n\n\ndef weight(model: Model, gamma: Mapping[str, Optional[int]]) -> float:\n    """log2 likelihood ratio plus prior odds: the Fellegi-Sunter match weight."""\n    p = min(max(posterior(model, gamma), 1e-12), 1 - 1e-12)\n    return math.log2(p / (1 - p))\n\n\n# ---------------------------------------------------------------------------\n# EM\n# ---------------------------------------------------------------------------\n\n\n@dataclass\nclass FitResult:\n    model: Model\n    iterations: int\n    converged: bool\n    log_likelihood: float\n    history: list[float]\n    pairs: int\n    #: Why a converged fit was still refused (see plausible()).\n    problems: tuple[str, ...] = ()\n\n\ndef _pattern(gamma: Mapping[str, Optional[int]], comparisons: Sequence[str]) -> tuple:\n    return tuple(gamma.get(c) for c in comparisons)\n\n\ndef _floor(values: list[float]) -> list[float]:\n    clipped = [max(x, v.PROBABILITY_FLOOR) for x in values]\n    total = sum(clipped)\n    return [x / total for x in clipped]\n\n\ndef fit_em(\n    gammas: Iterable[Mapping[str, Optional[int]]],\n    start: Model,\n    *,\n    max_iterations: int = v.EM_MAX_ITERATIONS,\n    tolerance: float = v.EM_TOLERANCE,\n    fixed_u: Optional[Mapping[str, Sequence[float]]] = None,\n) -> FitResult:\n    """EM for lambda, m and the BLOCKED comparisons\' u; every other u fixed.\n\n    Candidate pairs are chosen by name similarity, so among them a shared\n    surname says little: an EM free to move every u settles on "match =\n    shares a name token" and merges strangers (the G8 gate caught exactly\n    this). So u for the comparisons blocking did NOT select on (email,\n    phone, date of birth, the exclusive identifiers) is fixed from RANDOM\n    record pairs (estimate_u), which anchors the classes; only the name\'s u\n    is learned inside the blocked population. plausible() refuses any fit\n    whose evidence still points the wrong way.\n    """\n    comparisons = tuple(start.m)\n    counts = Counter(_pattern(g, comparisons) for g in gammas)\n    patterns = list(counts.items())\n    total = sum(counts.values())\n    fixed = dict(fixed_u or {})\n    model = Model(start.kind, start.lam, {c: list(x) for c, x in start.m.items()},\n                  {c: list(fixed.get(c, start.u[c])) for c in start.u})\n    history: list[float] = []\n    converged = False\n    iterations = 0\n    if total == 0:\n        return FitResult(model, 0, False, float("nan"), history, 0)\n\n    for iterations in range(1, max_iterations + 1):\n        m_acc = {c: [0.0] * LEVELS[c] for c in comparisons}\n        u_acc = {c: [0.0] * LEVELS[c] for c in comparisons}\n        g_sum = 0.0\n        ll = 0.0\n        for pattern, count in patterns:\n            gamma = dict(zip(comparisons, pattern))\n            pm, pu = likelihoods(model, gamma)\n            a, b = model.lam * pm, (1 - model.lam) * pu\n            g = a / (a + b)\n            ll += count * math.log(a + b)\n            g_sum += count * g\n            for c, level in gamma.items():\n                if level is None:\n                    continue\n                m_acc[c][level] += count * g\n                u_acc[c][level] += count * (1 - g)\n        history.append(ll)\n        new_lam = min(max(g_sum / total, 1e-6), 1 - 1e-6)\n        new_m = {c: _floor(x) if sum(x) > 0 else list(model.m[c]) for c, x in m_acc.items()}\n        new_u = {c: (list(model.u[c]) if c in fixed or sum(x) == 0 else _floor(x)) for c, x in u_acc.items()}\n        delta = abs(new_lam - model.lam)\n        for c in comparisons:\n            delta = max(delta, *(abs(p - q) for p, q in zip(new_m[c], model.m[c])),\n                        *(abs(p - q) for p, q in zip(new_u[c], model.u[c])))\n        model = Model(model.kind, new_lam, new_m, new_u)\n        if delta < tolerance:\n            converged = True\n            break\n\n    # Label guard: the "match" class must make an exact name MORE likely.\n    if not fixed and "name" in model.m and model.m["name"][-1] < model.u["name"][-1]:\n        model = Model(model.kind, 1 - model.lam, model.u, model.m)\n    final_ll = sum(\n        count * math.log(sum((model.lam * lm, (1 - model.lam) * lu)))\n        for pattern, count in patterns\n        for lm, lu in [likelihoods(model, dict(zip(comparisons, pattern)))]\n    )\n    problems = tuple(plausible(model))\n    return FitResult(model, iterations, converged and not problems, final_ll, history, total, problems)\n\n\ndef estimate_u(gammas: Iterable[Mapping[str, Optional[int]]], prior_model: Model) -> dict[str, list[float]]:\n    """u from comparisons of RANDOM record pairs: almost all are non-matches.\n\n    Laplace-smoothed; a comparison seen fewer than MIN_U_OBSERVATIONS times\n    keeps the prior\'s u.\n    """\n    comparisons = tuple(prior_model.u)\n    acc = {c: [0.5] * LEVELS[c] for c in comparisons}\n    seen = dict.fromkeys(comparisons, 0)\n    for gamma in gammas:\n        for c in comparisons:\n            level = gamma.get(c)\n            if level is not None:\n                acc[c][level] += 1\n                seen[c] += 1\n    return {c: (_floor(acc[c]) if seen[c] >= v.MIN_U_OBSERVATIONS else list(prior_model.u[c])) for c in comparisons}\n\n\ndef plausible(model: Model) -> list[str]:\n    """Why a model\'s evidence points the wrong way; empty when it does not.\n\n    For every comparison, full agreement must favour a match and full\n    disagreement must favour a non-match. A label-swapped fit fails this.\n    """\n    problems = []\n    for c in model.m:\n        m, u = model.m[c], model.u[c]\n        if m[-1] <= u[-1]:\n            problems.append(f"{c}: agreement is not evidence of a match")\n        if m[0] >= u[0]:\n            problems.append(f"{c}: disagreement is not evidence against a match")\n    return problems\n\n\ndef posterior_without_exclusive(model: Model, gamma: Mapping[str, Optional[int]]) -> float:\n    """The posterior on everything EXCEPT the exclusive identifiers.\n\n    This is what the conflict guard asks about: "apart from the two PANs, does\n    everything say these are the same party?" The full posterior already\n    counts the PAN disagreement heavily, so asking it would let the model\n    quietly answer "different" to exactly the question a human should see.\n    """\n    return posterior(model, {c: (None if c == "exclusive" else level) for c, level in gamma.items()})\n\n\n@dataclass(frozen=True)\nclass Decision:\n    outcome: str  # AUTO | REVIEW | NEW\n    reason: Optional[str]  # CONFLICT | UNCERTAIN | None\n    probability: float\n    weight: float\n\n\ndef decide(model: Model, gamma: Mapping[str, Optional[int]], conflict_kinds: Sequence[str]) -> Decision:\n    """AUTO (link), REVIEW (a human decides) or NEW (a separate record).\n\n    With a conflict, the guard decides and the model only says whether the\n    pair is worth a human\'s time: if the evidence other than the conflicting\n    identifiers reaches the review band, it goes to review as a CONFLICT;\n    otherwise the records are simply different. Never AUTO.\n    """\n    p = posterior(model, gamma)\n    w = weight(model, gamma)\n    if conflict_kinds:\n        apart = posterior_without_exclusive(model, gamma)\n        if apart >= v.REVIEW_PROBABILITY:\n            return Decision("REVIEW", v.REASON_CONFLICT, apart, w)\n        return Decision("NEW", None, p, w)\n    if p >= v.AUTO_LINK_PROBABILITY:\n        return Decision("AUTO", None, p, w)\n    if p >= v.REVIEW_PROBABILITY:\n        return Decision("REVIEW", v.REASON_UNCERTAIN, p, w)\n    return Decision("NEW", None, p, w)\n'),
